<?php namespace App\Http\Controllers; use App\Models\{User,Product,CareContent,AdoptionListing}; use Illuminate\Http\Request; class AdminController extends Controller { public function dashboard(){return ['users'=>User::count(),'products'=>Product::count(),'care_content'=>CareContent::count(),'adoptions'=>AdoptionListing::count()];} public function users(){return User::latest()->paginate(30);} public function updateUser(Request $r,User $user){$d=$r->validate(['role'=>'required|in:owner,vet,shelter,admin','is_active'=>'boolean']);$user->update($d);return $user;} }